# 简单的 RNN 单元实现示例
import numpy as np

class SimpleRNN:
    def __init__(self, input_size, hidden_size):
        self.Wx = np.random.randn(hidden_size, input_size)  # 输入权重
        self.Wh = np.random.randn(hidden_size, hidden_size)  # 隐藏状态权重
        self.b = np.zeros((hidden_size, 1))  # 偏置项
    
    def forward(self, x, h_prev):
        h_next = np.tanh(np.dot(self.Wx, x) + np.dot(self.Wh, h_prev) + self.b)
        return h_next

# 伪代码示例：基于词典的情感分析
def lexicon_based_sentiment(text):
    sentiment_score = 0
    words = tokenize(text)  # 分词
    for word in words:
        if word in positive_lexicon:
            sentiment_score += positive_lexicon[word]
        elif word in negative_lexicon:
            sentiment_score -= negative_lexicon[word]
    
    # 处理否定和程度修饰
    sentiment_score = apply_negation(words, sentiment_score)
    sentiment_score = apply_intensifier(words, sentiment_score)
    
    return normalize(sentiment_score)
